from AlgorithmImports import *
import math


class IndependentStrategySystemAlgorithm(QCAlgorithm):

    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1_000_000)

        self.symbols = {}
        for ticker in ("SPY", "AAPL", "IBM", "BAC", "AIG"):
            security = self.AddEquity(
                ticker,
                Resolution.Daily,
                Market.USA,
                False,
                0,
                False
            )
            self.symbols[ticker] = security.Symbol

        self.spy = self.symbols["SPY"]
        self.aapl = self.symbols["AAPL"]

        self.spy_sma = SimpleMovingAverage(20)
        self.spy_previous_close = None
        self.spy_previous_sma = None
        self.spy_crossed_above = False
        self.spy_crossed_below = False

        self.aapl_rsi = RelativeStrengthIndex(
            14,
            MovingAverageType.Wilders
        )
        self.aapl_previous_close = None
        self.aapl_red_streak = 0

        self.spy_lot = 0
        self.aapl_lot = 0

        self.SetWarmUp(21, Resolution.Daily)

    def OnData(self, data):
        self.spy_crossed_above = False
        self.spy_crossed_below = False

        bars = {}
        for ticker, symbol in self.symbols.items():
            if data.Bars.ContainsKey(symbol):
                bar = data.Bars[symbol]
                if not bar.IsFillForward:
                    bars[ticker] = bar

        if "SPY" in bars:
            spy_bar = bars["SPY"]
            spy_close = float(spy_bar.Close)

            self.spy_sma.Update(spy_bar.EndTime, spy_close)

            if self.spy_sma.IsReady:
                current_sma = float(self.spy_sma.Current.Value)

                if (
                    self.spy_previous_close is not None
                    and self.spy_previous_sma is not None
                ):
                    self.spy_crossed_above = (
                        self.spy_previous_close <= self.spy_previous_sma
                        and spy_close > current_sma
                    )
                    self.spy_crossed_below = (
                        self.spy_previous_close >= self.spy_previous_sma
                        and spy_close < current_sma
                    )

                self.spy_previous_close = spy_close
                self.spy_previous_sma = current_sma

        if "AAPL" in bars:
            aapl_bar = bars["AAPL"]
            aapl_close = float(aapl_bar.Close)

            if self.aapl_previous_close is not None:
                if aapl_close < self.aapl_previous_close:
                    self.aapl_red_streak += 1
                else:
                    self.aapl_red_streak = 0

            self.aapl_previous_close = aapl_close
            self.aapl_rsi.Update(aapl_bar.EndTime, aapl_close)

        if self.IsWarmingUp:
            return

        if len(bars) != len(self.symbols):
            return

        if (
            self.spy_previous_sma is None
            or not self.aapl_rsi.IsReady
            or self.aapl_previous_close is None
        ):
            return

        spy_close = float(bars["SPY"].Close)
        aapl_close = float(bars["AAPL"].Close)

        # Evaluate all sells before any buys.
        if self.spy_lot > 0 and self.spy_crossed_below:
            quantity = self.spy_lot
            ticket = self.MarketOrder(
                self.spy,
                -quantity,
                False,
                "Strategy A: close crossed below SMA"
            )
            if ticket is not None and ticket.Status != OrderStatus.Invalid:
                self.spy_lot = 0

        if (
            self.aapl_lot > 0
            and float(self.aapl_rsi.Current.Value) > 60.0
        ):
            quantity = self.aapl_lot
            ticket = self.MarketOrder(
                self.aapl,
                -quantity,
                False,
                "Strategy B: RSI above 60"
            )
            if ticket is not None and ticket.Status != OrderStatus.Invalid:
                self.aapl_lot = 0

        if self.spy_lot == 0 and self.spy_crossed_above:
            target_value = (
                0.40 * float(self.Portfolio.TotalPortfolioValue)
            )
            quantity = int(math.floor(target_value / spy_close))

            if quantity > 0:
                ticket = self.MarketOrder(
                    self.spy,
                    quantity,
                    False,
                    "Strategy A: close crossed above SMA"
                )
                if (
                    ticket is not None
                    and ticket.Status != OrderStatus.Invalid
                ):
                    self.spy_lot = quantity

        if self.aapl_lot == 0 and self.aapl_red_streak >= 3:
            if float(self.Portfolio.Cash) >= 20_000.0:
                quantity = int(math.floor(20_000.0 / aapl_close))

                if quantity > 0:
                    ticket = self.MarketOrder(
                        self.aapl,
                        quantity,
                        False,
                        "Strategy B: three or more red days"
                    )
                    if (
                        ticket is not None
                        and ticket.Status != OrderStatus.Invalid
                    ):
                        self.aapl_lot = quantity

