from AlgorithmImports import *
import math


class StrategySystemAlgorithm(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1_000_000)

        self.symbols = {}
        for ticker in ["SPY", "AAPL", "IBM", "BAC", "AIG"]:
            self.symbols[ticker] = self.AddEquity(ticker, Resolution.Daily).Symbol

        self.spy = self.symbols["SPY"]
        self.aapl = self.symbols["AAPL"]

        self.sma_period = 20
        self.spy_sma = SimpleMovingAverage(self.sma_period)
        self.aapl_rsi = RelativeStrengthIndex(14, MovingAverageType.Wilders)

        self.previous_spy_close = None
        self.previous_spy_sma = None
        self.previous_aapl_close = None
        self.aapl_red_streak = 0

        self.strategy_a_shares = 0
        self.strategy_b_shares = 0
        self.strategy_a_order_id = None
        self.strategy_b_order_id = None

        self.SetWarmUp(self.sma_period + 1, Resolution.Daily)

    def OnData(self, data):
        self.strategy_a_shares = max(
            0, int(self.Portfolio[self.spy].Quantity)
        )
        self.strategy_b_shares = max(
            0, int(self.Portfolio[self.aapl].Quantity)
        )

        prior_spy_close = self.previous_spy_close
        prior_spy_sma = self.previous_spy_sma
        prior_aapl_close = self.previous_aapl_close

        spy_bar = data.Bars[self.spy] if self.spy in data.Bars else None
        aapl_bar = data.Bars[self.aapl] if self.aapl in data.Bars else None

        current_spy_sma = None
        if spy_bar is not None:
            self.spy_sma.Update(spy_bar.EndTime, spy_bar.Close)
            if self.spy_sma.IsReady:
                current_spy_sma = self.spy_sma.Current.Value
                self.previous_spy_sma = current_spy_sma
            self.previous_spy_close = spy_bar.Close

        if aapl_bar is not None:
            if prior_aapl_close is not None:
                if aapl_bar.Close < prior_aapl_close:
                    self.aapl_red_streak += 1
                else:
                    self.aapl_red_streak = 0

            self.aapl_rsi.Update(aapl_bar.EndTime, aapl_bar.Close)
            self.previous_aapl_close = aapl_bar.Close

        if self.IsWarmingUp:
            return

        if any(symbol not in data.Bars for symbol in self.symbols.values()):
            return

        if (
            not self.spy_sma.IsReady
            or not self.aapl_rsi.IsReady
            or prior_spy_close is None
            or prior_spy_sma is None
            or current_spy_sma is None
            or prior_aapl_close is None
        ):
            return

        spy_close = spy_bar.Close
        aapl_close = aapl_bar.Close

        if self.strategy_a_shares > 0 and self.strategy_a_order_id is None:
            crosses_below = (
                prior_spy_close >= prior_spy_sma
                and spy_close < current_spy_sma
            )
            if crosses_below:
                ticket = self.MarketOrder(
                    self.spy,
                    -self.strategy_a_shares,
                    tag="Strategy A sell"
                )
                self.strategy_a_order_id = ticket.OrderId

        if self.strategy_b_shares > 0 and self.strategy_b_order_id is None:
            if self.aapl_rsi.Current.Value > 60:
                ticket = self.MarketOrder(
                    self.aapl,
                    -self.strategy_b_shares,
                    tag="Strategy B sell"
                )
                self.strategy_b_order_id = ticket.OrderId

        if self.strategy_a_shares == 0 and self.strategy_a_order_id is None:
            crosses_above = (
                prior_spy_close <= prior_spy_sma
                and spy_close > current_spy_sma
            )
            if crosses_above:
                quantity = int(
                    math.floor(
                        0.40 * self.Portfolio.TotalPortfolioValue / spy_close
                    )
                )
                if quantity > 0:
                    ticket = self.MarketOrder(
                        self.spy,
                        quantity,
                        tag="Strategy A buy"
                    )
                    self.strategy_a_order_id = ticket.OrderId

        if self.strategy_b_shares == 0 and self.strategy_b_order_id is None:
            if (
                self.aapl_red_streak >= 3
                and self.Portfolio.Cash >= 20_000
            ):
                quantity = int(math.floor(20_000 / aapl_close))
                if quantity > 0:
                    ticket = self.MarketOrder(
                        self.aapl,
                        quantity,
                        tag="Strategy B buy"
                    )
                    self.strategy_b_order_id = ticket.OrderId

    def OnOrderEvent(self, order_event):
        if order_event.Status not in [
            OrderStatus.Filled,
            OrderStatus.Canceled,
            OrderStatus.Invalid
        ]:
            return

        if order_event.OrderId == self.strategy_a_order_id:
            self.strategy_a_order_id = None
            self.strategy_a_shares = max(
                0, int(self.Portfolio[self.spy].Quantity)
            )

        if order_event.OrderId == self.strategy_b_order_id:
            self.strategy_b_order_id = None
            self.strategy_b_shares = max(
                0, int(self.Portfolio[self.aapl].Quantity)
            )

