from AlgorithmImports import *
from collections import deque
from math import floor


class ExactStrategySystemAlgorithm(QCAlgorithm):
    SPY_MOVING_AVERAGE_PERIOD = 20
    RSI_PERIOD = 14

    def initialize(self):
        self.set_start_date(2006, 1, 3)
        self.set_end_date(2015, 12, 31)
        self.set_cash(1_000_000)

        self.spy = self.add_equity("SPY", Resolution.DAILY).symbol
        self.aapl = self.add_equity("AAPL", Resolution.DAILY).symbol
        self.ibm = self.add_equity("IBM", Resolution.DAILY).symbol
        self.bac = self.add_equity("BAC", Resolution.DAILY).symbol
        self.aig = self.add_equity("AIG", Resolution.DAILY).symbol

        self.subscribed_symbols = [
            self.spy,
            self.aapl,
            self.ibm,
            self.bac,
            self.aig
        ]

        self.spy_closes = deque(maxlen=self.SPY_MOVING_AVERAGE_PERIOD)
        self.previous_spy_close = None
        self.previous_spy_average = None

        self.previous_aapl_close = None
        self.aapl_red_streak = 0
        self.rsi_changes = 0
        self.rsi_initial_gains = 0.0
        self.rsi_initial_losses = 0.0
        self.rsi_average_gain = None
        self.rsi_average_loss = None
        self.current_aapl_rsi = None

    def on_data(self, data):
        spy_crossed_above = False
        spy_crossed_below = False

        if data.bars.contains_key(self.spy):
            spy_close = float(data.bars[self.spy].close)
            self.spy_closes.append(spy_close)

            current_spy_average = None
            if len(self.spy_closes) == self.SPY_MOVING_AVERAGE_PERIOD:
                current_spy_average = (
                    sum(self.spy_closes) / self.SPY_MOVING_AVERAGE_PERIOD
                )

            if (
                current_spy_average is not None
                and self.previous_spy_close is not None
                and self.previous_spy_average is not None
            ):
                spy_crossed_above = (
                    self.previous_spy_close <= self.previous_spy_average
                    and spy_close > current_spy_average
                )
                spy_crossed_below = (
                    self.previous_spy_close >= self.previous_spy_average
                    and spy_close < current_spy_average
                )

            self.previous_spy_close = spy_close
            self.previous_spy_average = current_spy_average

        if data.bars.contains_key(self.aapl):
            aapl_close = float(data.bars[self.aapl].close)

            if self.previous_aapl_close is not None:
                change = aapl_close - self.previous_aapl_close

                if change < 0:
                    self.aapl_red_streak += 1
                else:
                    self.aapl_red_streak = 0

                gain = max(change, 0.0)
                loss = max(-change, 0.0)

                if self.rsi_changes < self.RSI_PERIOD:
                    self.rsi_initial_gains += gain
                    self.rsi_initial_losses += loss
                    self.rsi_changes += 1

                    if self.rsi_changes == self.RSI_PERIOD:
                        self.rsi_average_gain = (
                            self.rsi_initial_gains / self.RSI_PERIOD
                        )
                        self.rsi_average_loss = (
                            self.rsi_initial_losses / self.RSI_PERIOD
                        )
                else:
                    self.rsi_average_gain = (
                        self.rsi_average_gain * (self.RSI_PERIOD - 1) + gain
                    ) / self.RSI_PERIOD
                    self.rsi_average_loss = (
                        self.rsi_average_loss * (self.RSI_PERIOD - 1) + loss
                    ) / self.RSI_PERIOD

                if self.rsi_changes >= self.RSI_PERIOD:
                    if self.rsi_average_loss == 0:
                        self.current_aapl_rsi = 100.0
                    else:
                        relative_strength = (
                            self.rsi_average_gain / self.rsi_average_loss
                        )
                        self.current_aapl_rsi = (
                            100.0 - 100.0 / (1.0 + relative_strength)
                        )

