from AlgorithmImports import *
from math import floor


class ExactStrategySystemAlgorithm(QCAlgorithm):

    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1_000_000)

        self.symbols = {}
        for ticker in ["SPY", "AAPL", "IBM", "BAC", "AIG"]:
            self.symbols[ticker] = self.AddEquity(
                ticker, Resolution.Daily
            ).Symbol

        self.spy_closes = []
        self.aapl_previous_close = None
        self.aapl_close_count = 0
        self.aapl_red_streak = 0

        self.aapl_rsi_delta_count = 0
        self.aapl_initial_gain_sum = 0.0
        self.aapl_initial_loss_sum = 0.0
        self.aapl_average_gain = None
        self.aapl_average_loss = None
        self.aapl_rsi = None

        self.SetWarmUp(101, Resolution.Daily)

    def OnData(self, data):
        bars = {}

        for ticker, symbol in self.symbols.items():
            if data.Bars.ContainsKey(symbol):
                bars[ticker] = data.Bars[symbol]

        if "SPY" in bars:
            self._update_spy(float(bars["SPY"].Close))

        if "AAPL" in bars:
            self._update_aapl(float(bars["AAPL"].Close))

        if self.IsWarmingUp:
            return

        if len(bars) != len(self.symbols):
            return

        if not self._all_state_ready():
            return

        spy_crosses_above, spy_crosses_below = self._spy_crosses()
        aapl_close = float(bars["AAPL"].Close)

        spy_symbol = self.symbols["SPY"]
        aapl_symbol = self.symbols["AAPL"]

        # Evaluate and execute every sell before evaluating any buy.
        if self._lot_quantity(spy_symbol) > 0:
            if (
                not self._has_open_order(spy_symbol)
                and spy_crosses_below
            ):
                self.MarketOrder(
                    spy_symbol,
                    -self._lot_quantity(spy_symbol),
                    tag="Strategy A liquidation"
                )

        if self._lot_quantity(aapl_symbol) > 0:
            if (
                not self._has_open_order(aapl_symbol)
                and self.aapl_rsi > 60.0
            ):
                self.MarketOrder(
                    aapl_symbol,
                    -self._lot_quantity(aapl_symbol),
                    tag="Strategy B liquidation"
                )

        if (
            self._lot_quantity(spy_symbol) == 0
            and not self._has_open_order(spy_symbol)
            and spy_crosses_above
        ):
            target_value = (
                0.40 * float(self.Portfolio.TotalPortfolioValue)
            )
            spy_close = float(bars["SPY"].Close)
            quantity = floor(target_value / spy_close)

            if quantity > 0:
                self.MarketOrder(
                    spy_symbol,
                    quantity,
                    tag="Strategy A entry"
                )

        if (
            self._lot_quantity(aapl_symbol) == 0
            and not self._has_open_order(aapl_symbol)
            and self.aapl_red_streak >= 3
            and float(self.Portfolio.Cash) >= 20_000.0
        ):
            quantity = floor(20_000.0 / aapl_close)

            if quantity > 0:
                self.MarketOrder(
                    aapl_symbol,
                    quantity,
                    tag="Strategy B entry"
                )

    def _update_spy(self, close):
        self.spy_closes.append(close)

        if len(self.spy_closes) > 101:
            self.spy_closes.pop(0)

    def _update_aapl(self, close):
        self.aapl_close_count += 1

        if self.aapl_previous_close is None:
            self.aapl_previous_close = close
            return

        change = close - self.aapl_previous_close

        if change < 0.0:
            self.aapl_red_streak += 1
        else:
            self.aapl_red_streak = 0

        gain = max(change, 0.0)
        loss = max(-change, 0.0)

        if self.aapl_rsi_delta_count < 14:
            self.aapl_initial_gain_sum += gain
            self.aapl_initial_loss_sum += loss
            self.aapl_rsi_delta_count += 1

            if self.aapl_rsi_delta_count == 14:
                self.aapl_average_gain = (
                    self.aapl_initial_gain_sum / 14.0
                )
                self.aapl_average_loss = (
                    self.aapl_initial_loss_sum / 14.0
                )
                self.aapl_rsi = self._calculate_rsi(
                    self.aapl_average_gain,
                    self.aapl_average_loss
                )
        else:
            self.aapl_average_gain = (
                (self.aapl_average_gain * 13.0) + gain
            ) / 14.0
            self.aapl_average_loss = (
                (self.aapl_average_loss * 13.0) + loss
            ) / 14.0
            self.aapl_rsi = self._calculate_rsi(
                self.aapl_average_gain,
                self.aapl_average_loss
            )

        self.aapl_previous_close = close

    def _calculate_rsi(self, average_gain, average_loss):
        if average_loss == 0.0:
            return 100.0

        relative_strength = average_gain / average_loss
        return 100.0 - (100.0 / (1.0 + relative_strength))

    def _all_state_ready(self):
        return (
            len(self.spy_closes) == 101
            and self.aapl_close_count >= 4
            and self.aapl_rsi_delta_count >= 14
            and self.aapl_rsi is not None
        )

    def _spy_crosses(self):
        previous_close = self.spy_closes[-2]
        current_close = self.spy_closes[-1]

        previous_sma = sum(self.spy_closes[:-1]) / 100.0
        current_sma = sum(self.spy_closes[1:]) / 100.0

        crosses_above = (
            previous_close <= previous_sma
            and current_close > current_sma
        )
        crosses_below = (
            previous_close >= previous_sma
            and current_close < current_sma
        )

        return crosses_above, crosses_below

    def _lot_quantity(self, symbol):
        return max(0, int(self.Portfolio[symbol].Quantity))

    def _has_open_order(self, symbol):
        return len(self.Transactions.GetOpenOrders(symbol)) > 0

