            if self.spy_sma.IsReady:
                self.previous_spy_close = spy_bar.Close
                self.previous_spy_sma = self.spy_sma.Current.Value

        if data.Bars.ContainsKey(self.aapl):
            aapl_bar = data.Bars[self.aapl]
            self.aapl_rsi.Update(aapl_bar.EndTime, aapl_bar.Close)

            if self.previous_aapl_close is not None:
                if aapl_bar.Close < self.previous_aapl_close:
                    self.aapl_red_streak += 1
                else:
                    self.aapl_red_streak = 0

            self.previous_aapl_close = aapl_bar.Close

        if not all_bars_present:
            return

        if (
            not self.spy_sma.IsReady
            or self.previous_spy_sma is None
            or not self.aapl_rsi.IsReady
        ):
            return

        spy_invested = self.Portfolio[self.spy].Quantity != 0
        aapl_invested = self.Portfolio[self.aapl].Quantity != 0

        if spy_invested and spy_crossed_below:
            self.Liquidate(self.spy)

        if aapl_invested and self.aapl_rsi.Current.Value > 60:
            self.Liquidate(self.aapl)

        if not spy_invested and spy_crossed_above:
            self.SetHoldings(self.spy, 0.40)

        if not aapl_invested and self.aapl_red_streak >= 3:
            if self.Portfolio.Cash >= 20_000:
                quantity = math.floor(
                    20_000 / float(data.Bars[self.aapl].Close)
                )
                if quantity > 0:
                    self.MarketOrder(self.aapl, quantity)
